insert into public.concepts (id, skill_area_id, title, official_summary, reviewed, sort_order) values
('cloud-models', 'cloud_concepts', 'Cloud models: public, private and hybrid', 'A public cloud is owned and run by a provider and shared by many customers over the internet. A private cloud is used by a single organization and can be hosted on premises or by a provider. A hybrid cloud combines public and private clouds so apps and data can move between them.', false, 9),
('consumption-capex-opex', 'cloud_concepts', 'Consumption model, CapEx and OpEx', 'In the consumption based model you pay only for the resources you use, with no upfront purchase. Capital expenditure (CapEx) is upfront spending on physical infrastructure. Operational expenditure (OpEx) is spending on services as you use them. Moving to the cloud shifts spending from CapEx to OpEx.', false, 10),
('scalability-elasticity', 'cloud_concepts', 'Scalability and elasticity', 'Scalability is the ability to adjust resources to meet demand. Vertical scaling adds power to an existing machine, and horizontal scaling adds more machines. Elasticity is the ability to scale out and in automatically as demand changes, so you pay only for what is needed.', false, 11),
('high-availability', 'cloud_concepts', 'High availability and reliability', 'High availability means a workload stays accessible with minimal downtime. Reliability is the ability to recover from failures and keep working. Azure supports both with availability zones, region pairs and Service Level Agreements.', false, 12),
('serverless', 'cloud_concepts', 'Serverless computing', 'Serverless computing lets you run code without managing servers. The platform provisions and scales resources automatically, and you pay only while your code runs. Azure Functions is an example of a serverless service.', false, 13),

('region-pairs', 'architecture_services', 'Region pairs', 'Most Azure regions are paired with another region in the same geography, usually far apart, to support recovery from a large regional disaster. If a wide outage affects many regions, one region in each pair is prioritized for recovery. Platform updates are rolled out to one region in a pair at a time. Some regions are not paired.', false, 14),
('resource-groups', 'architecture_services', 'Resources and resource groups', 'A resource is a manageable item such as a virtual machine or a storage account. A resource group is a logical container for resources that share a lifecycle. Every resource belongs to exactly one resource group, and deleting a resource group deletes the resources inside it. Resource groups cannot be nested.', false, 15),
('subscriptions-management-groups', 'architecture_services', 'Subscriptions and management groups', 'A subscription is a unit of management, billing and scale that holds resource groups. Management groups sit above subscriptions and let you apply policy and access control across many subscriptions. The hierarchy is management groups, subscriptions, resource groups, then resources.', false, 16),
('virtual-machines', 'architecture_services', 'Azure Virtual Machines', 'Azure Virtual Machines are IaaS compute that give you full control of the operating system and software. They suit custom configurations and lift and shift of existing apps. You are responsible for patching and maintaining the guest operating system.', false, 17),
('scale-sets-availability-sets', 'architecture_services', 'Scale sets and availability sets', 'Virtual machine scale sets manage a group of identical load balanced virtual machines that can scale automatically with demand. Availability sets spread virtual machines across fault domains and update domains inside a datacenter to reduce downtime from hardware faults and maintenance. Availability zones protect against the failure of a whole datacenter.', false, 18),
('containers', 'architecture_services', 'Containers, ACI and AKS', 'Containers package an app with its dependencies and share the host operating system, so they start fast and use fewer resources than virtual machines. Azure Container Instances runs containers without managing servers. Azure Kubernetes Service (AKS) is a managed Kubernetes service for orchestrating many containers.', false, 19),
('app-service', 'architecture_services', 'Azure App Service', 'Azure App Service is a PaaS offering for hosting web apps, REST APIs and mobile back ends. It supports several languages and the platform handles infrastructure, scaling and patching of the underlying servers.', false, 20),
('azure-functions', 'architecture_services', 'Azure Functions', 'Azure Functions is a serverless, event driven compute service. Code runs in response to triggers such as HTTP requests, timers or queue messages. It scales automatically, and on the consumption plan you are billed for execution.', false, 21),
('virtual-network', 'architecture_services', 'Virtual networks', 'An Azure Virtual Network (VNet) is a private network in Azure that lets resources such as virtual machines communicate securely with each other, the internet and on premises networks. Subnets divide a VNet into smaller ranges. VNet peering connects two VNets over the Microsoft backbone network. Network security groups filter network traffic.', false, 22),
('vpn-expressroute', 'architecture_services', 'VPN Gateway and ExpressRoute', 'VPN Gateway sends encrypted traffic over the public internet between an on premises network and an Azure virtual network. ExpressRoute uses a private connection through a connectivity provider and does not travel over the public internet, which gives more reliability, higher speeds and lower latency.', false, 23),
('dns-endpoints', 'architecture_services', 'Azure DNS and endpoints', 'Azure DNS hosts DNS domains and resolves names using Microsoft infrastructure. A public endpoint is reachable over the internet. A private endpoint uses a private IP address from your virtual network, through Azure Private Link, so a service is reached privately.', false, 24),
('storage-services', 'architecture_services', 'Azure Storage services', 'Azure Storage includes Blob storage for unstructured data such as images and backups, Azure Files for managed file shares over SMB or NFS, Queue storage for messages between application components, and Table storage for NoSQL key and attribute data. Managed disks provide block storage for virtual machines.', false, 25),
('storage-redundancy', 'architecture_services', 'Storage redundancy', 'Locally redundant storage (LRS) keeps three copies within a single location. Zone redundant storage (ZRS) copies data across three availability zones in one region. Geo redundant storage (GRS) adds an asynchronous copy to a secondary region. Geo zone redundant storage (GZRS) combines ZRS in the primary region with a copy in a secondary region. Read access variants allow reading from the secondary region.', false, 26),
('access-tiers', 'architecture_services', 'Blob access tiers', 'Hot tier is for data accessed frequently. Cool tier is for infrequently accessed data kept for at least 30 days. Cold tier is for rarely accessed data kept for at least 90 days. Archive tier is for rarely accessed data kept for at least 180 days and is offline, so retrieval takes hours. Cooler tiers cost less to store and more to access.', false, 27),
('data-movement', 'architecture_services', 'Moving data to Azure', 'AzCopy is a command line tool for copying data to and from Azure Storage. Azure Storage Explorer is a graphical app for managing storage. Azure Migrate is a hub for assessing and migrating on premises servers, databases and apps to Azure. Azure Data Box is a physical device for moving large amounts of data offline.', false, 28),
('entra-id', 'architecture_services', 'Microsoft Entra ID', 'Microsoft Entra ID, formerly Azure Active Directory, is a cloud based identity and access management service used to sign in and access resources. Microsoft Entra Domain Services provides managed domain services such as domain join, group policy and LDAP without running your own domain controllers.', false, 29),
('auth-sso-mfa', 'architecture_services', 'Authentication, SSO and MFA', 'Authentication proves who you are, and authorization decides what you can do. Single sign on lets a user sign in once to reach many apps. Multifactor authentication requires two or more verification methods. Passwordless options include Windows Hello for Business, Microsoft Authenticator and FIDO2 security keys.', false, 30),
('conditional-access', 'architecture_services', 'Conditional Access', 'Microsoft Entra Conditional Access is a policy engine that evaluates signals such as user, location, device and risk, then enforces a decision such as requiring multifactor authentication, requiring a compliant device or blocking access. Policies work as if then rules.', false, 31),
('zero-trust-defence', 'architecture_services', 'Zero Trust and defence in depth', 'Zero Trust follows three principles: verify explicitly, use least privilege access and assume breach. Defence in depth protects with layers: physical security, identity and access, perimeter, network, compute, application and data.', false, 32),
('defender-for-cloud', 'architecture_services', 'Microsoft Defender for Cloud', 'Microsoft Defender for Cloud is a tool for cloud security posture management and workload protection. It assesses your resources, gives security recommendations and a secure score, and protects workloads in Azure, on premises and in other clouds.', false, 33),

('cost-factors', 'management_governance', 'Factors that affect cost', 'Azure cost depends on the resource type, how much you use, the region, the subscription type and network traffic. Inbound data transfer is generally free while outbound data transfer is charged. Reservations and Azure Hybrid Benefit can lower cost.', false, 34),
('pricing-tco-calculators', 'management_governance', 'Pricing and TCO calculators', 'The Pricing calculator estimates the cost of the Azure services you plan to use. The Total Cost of Ownership (TCO) calculator compares the cost of running workloads on premises with running them in Azure.', false, 35),
('cost-management-tags', 'management_governance', 'Cost Management and tags', 'Microsoft Cost Management lets you analyse spending, set budgets and alerts, and get cost saving recommendations. Tags are name and value pairs added to resources that help you organize resources and filter cost reports by department, project or environment.', false, 36),
('resource-locks', 'management_governance', 'Resource locks', 'Resource locks prevent accidental deletion or modification of resources. A CanNotDelete lock lets users read and modify but not delete. A ReadOnly lock lets users read but not modify or delete. Locks apply to all users including owners and are inherited by child resources.', false, 37),
('purview', 'management_governance', 'Microsoft Purview and Service Trust Portal', 'Microsoft Purview is a set of governance, risk and compliance solutions for data. It maps and classifies data across on premises, multicloud and SaaS sources. The Service Trust Portal provides Microsoft compliance, audit and privacy reports.', false, 38),
('portal-cloud-shell', 'management_governance', 'Azure portal and Cloud Shell', 'The Azure portal is a web based graphical interface for managing Azure. Azure Cloud Shell is a browser based command line that supports Bash and PowerShell with common tools already installed.', false, 39),
('cli-powershell', 'management_governance', 'Azure CLI and PowerShell', 'Azure CLI and Azure PowerShell are command line tools for managing Azure and automating tasks with scripts. They run on Windows, macOS and Linux. Azure CLI commands start with az, and Azure PowerShell uses cmdlets such as New-AzVM.', false, 40),
('azure-arc', 'management_governance', 'Azure Arc', 'Azure Arc extends Azure management to resources outside Azure, such as on premises servers, Kubernetes clusters and other clouds. It projects them into Azure Resource Manager so they can use tools such as Azure Policy, role based access control and monitoring.', false, 41),
('arm-bicep', 'management_governance', 'ARM templates and Bicep', 'Infrastructure as code defines resources in files so deployments are repeatable and consistent. Azure Resource Manager (ARM) is the deployment and management service for Azure. ARM templates are declarative JSON files. Bicep is a simpler language that compiles to ARM templates.', false, 42),
('azure-advisor', 'management_governance', 'Azure Advisor', 'Azure Advisor analyses your resource configuration and usage and gives personalized recommendations in five categories: reliability, security, performance, cost and operational excellence.', false, 43),
('service-health', 'management_governance', 'Azure Service Health', 'Azure Service Health tracks Azure service issues, planned maintenance and health advisories that affect your resources and can send alerts. Azure status shows the global health of Azure services. Resource health shows the health of your individual resources.', false, 44),
('azure-monitor', 'management_governance', 'Azure Monitor', 'Azure Monitor collects, analyses and acts on telemetry from cloud and on premises environments. It includes metrics, logs queried with Log Analytics, alerts, and Application Insights for monitoring application performance.', false, 45),
('sla-lifecycle', 'management_governance', 'SLAs and service lifecycle', 'A Service Level Agreement (SLA) describes the uptime and connectivity commitment Microsoft makes for a service, expressed as a percentage. A higher percentage means less allowed downtime. Services in preview are usually not covered by an SLA, while generally available (GA) services are.', false, 46)
on conflict (id) do nothing;